CREATE     PROCEDURE [synapse_fo].[usp_Update_DIMENSIONATTRIBUTE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:35
	Description: Update stored procedure for DIMENSIONATTRIBUTE from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[BACKINGENTITYKEYFIELDID] = stg.[BACKINGENTITYKEYFIELDID],
		tgt.[BACKINGENTITYKEYFIELDNAME] = stg.[BACKINGENTITYKEYFIELDNAME],
		tgt.[BACKINGENTITYTABLEID] = stg.[BACKINGENTITYTABLEID],
		tgt.[BACKINGENTITYTABLENAME] = stg.[BACKINGENTITYTABLENAME],
		tgt.[BACKINGENTITYTYPE] = stg.[BACKINGENTITYTYPE],
		tgt.[BACKINGENTITYVALUEFIELDID] = stg.[BACKINGENTITYVALUEFIELDID],
		tgt.[BACKINGENTITYVALUEFIELDNAME] = stg.[BACKINGENTITYVALUEFIELDNAME],
		tgt.[BALANCINGDIMENSION_PSN] = stg.[BALANCINGDIMENSION_PSN],
		tgt.[COPYVALUESONCREATE] = stg.[COPYVALUESONCREATE],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DIMENSIONKEYCOLUMNNAME] = stg.[DIMENSIONKEYCOLUMNNAME],
		tgt.[DIMENSIONVALUECOLUMNNAME] = stg.[DIMENSIONVALUECOLUMNNAME],
		--tgt.[FileName] = stg.[FileName],
		tgt.[GIVEDERIVEDDIMENSIONSPRECEDENCE] = stg.[GIVEDERIVEDDIMENSIONSPRECEDENCE],
		tgt.[HASHKEY] = stg.[HASHKEY],
		tgt.[ISBALANCING_PSN] = stg.[ISBALANCING_PSN],
		tgt.[KEYATTRIBUTE] = stg.[KEYATTRIBUTE],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[NAME] = stg.[NAME],
		tgt.[NAMEATTRIBUTE] = stg.[NAMEATTRIBUTE],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[REPORTCOLUMNNAME] = stg.[REPORTCOLUMNNAME],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TRANSLATIONKEYFIELDID] = stg.[TRANSLATIONKEYFIELDID],
		tgt.[TRANSLATIONKEYFIELDNAME] = stg.[TRANSLATIONKEYFIELDNAME],
		tgt.[TRANSLATIONLANGUAGEIDFIELDID] = stg.[TRANSLATIONLANGUAGEIDFIELDID],
		tgt.[TRANSLATIONLANGUAGEIDFIELDNAME] = stg.[TRANSLATIONLANGUAGEIDFIELDNAME],
		tgt.[TRANSLATIONNAMEFIELDID] = stg.[TRANSLATIONNAMEFIELDID],
		tgt.[TRANSLATIONNAMEFIELDNAME] = stg.[TRANSLATIONNAMEFIELDNAME],
		tgt.[TRANSLATIONTABLEID] = stg.[TRANSLATIONTABLEID],
		tgt.[TRANSLATIONTABLENAME] = stg.[TRANSLATIONTABLENAME],
		tgt.[TRANSLATIONVIEWID] = stg.[TRANSLATIONVIEWID],
		tgt.[TRANSLATIONVIEWKEYFIELDID] = stg.[TRANSLATIONVIEWKEYFIELDID],
		tgt.[TRANSLATIONVIEWKEYFIELDNAME] = stg.[TRANSLATIONVIEWKEYFIELDNAME],
		tgt.[TRANSLATIONVIEWLANGUAGEIDFIELDID] = stg.[TRANSLATIONVIEWLANGUAGEIDFIELDID],
		tgt.[TRANSLATIONVIEWLANGUAGEIDFIELDNAME] = stg.[TRANSLATIONVIEWLANGUAGEIDFIELDNAME],
		tgt.[TRANSLATIONVIEWNAME] = stg.[TRANSLATIONVIEWNAME],
		tgt.[TRANSLATIONVIEWNAMEFIELDID] = stg.[TRANSLATIONVIEWNAMEFIELDID],
		tgt.[TRANSLATIONVIEWNAMEFIELDNAME] = stg.[TRANSLATIONVIEWNAMEFIELDNAME],
		tgt.[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDID] = stg.[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDID],
		tgt.[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDNAME] = stg.[TRANSLATIONVIEWSYSTEMLANGUAGEIDFIELDNAME],
		tgt.[TRANSLATIONVIEWTRANSLATEDNAMEFIELDID] = stg.[TRANSLATIONVIEWTRANSLATEDNAMEFIELDID],
		tgt.[TRANSLATIONVIEWTRANSLATEDNAMEFIELDNAME] = stg.[TRANSLATIONVIEWTRANSLATEDNAMEFIELDNAME],
		tgt.[TRANSLATIONVIEWVALUEFIELDID] = stg.[TRANSLATIONVIEWVALUEFIELDID],
		tgt.[TRANSLATIONVIEWVALUEFIELDNAME] = stg.[TRANSLATIONVIEWVALUEFIELDNAME],
		tgt.[TYPE] = stg.[TYPE],
		tgt.[USETRANSLATIONNAMEMETHOD] = stg.[USETRANSLATIONNAMEMETHOD],
		tgt.[VALUEATTRIBUTE] = stg.[VALUEATTRIBUTE],
		tgt.[VIEWNAME] = stg.[VIEWNAME]
	 FROM [synapse_fo].[DIMENSIONATTRIBUTE] tgt
		INNER JOIN [staging_fo].[DIMENSIONATTRIBUTE] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
